const parsePositiveRate = (value) => {
  const number = Number(String(value ?? "").replace(/\s/g, "").replace(",", "."));
  return Number.isFinite(number) && number > 0 ? number : 0;
};

const validExchangeRateMap = (rates = {}) => {
  const usd = parsePositiveRate(rates.USD);
  const eur = parsePositiveRate(rates.EUR);
  const rub = parsePositiveRate(rates.RUB);
  const gel = parsePositiveRate(rates.GEL);
  if (!usd || !eur || !rub || !gel) return false;
  if (usd < 5 || usd > 250) return false;
  if (eur < 5 || eur > 300 || eur < usd * 0.5) return false;
  if (rub < 0.01 || rub > 10) return false;
  if (gel < 0.5 || gel > 100) return false;
  return true;
};

const ADMIN_RATE_CACHE_KEY = "sidya-admin-valid-exchange-rates";
const LEGACY_RATE_CACHE_KEYS = [
  "sidya-admin-exchange-rates",
  "sidyaExchangeRates",
  "exchangeRates",
  "exchange-rates",
  "SIDYA_ADMIN_EXCHANGE_RATES",
];

const clearLegacyExchangeRateCaches = () => {
  try {
    LEGACY_RATE_CACHE_KEYS.forEach((key) => localStorage.removeItem(key));
    const cached = JSON.parse(localStorage.getItem(ADMIN_RATE_CACHE_KEY) || "{}");
    if (cached?.rates && !validExchangeRateMap(cached.rates)) {
      localStorage.removeItem(ADMIN_RATE_CACHE_KEY);
    }
  } catch {
    try { localStorage.removeItem(ADMIN_RATE_CACHE_KEY); } catch {}
  }
};

const normalizeExchangeRates = (payload = {}) => {
  const rates = payload.rates || payload;
  const list = Array.isArray(rates) ? rates : Array.isArray(payload.rateList) ? payload.rateList : [];
  const map = {};

  if (rates && typeof rates === "object" && !Array.isArray(rates)) {
    ["USD", "EUR", "RUB", "GEL"].forEach((code) => {
      const value = parsePositiveRate(rates[code] ?? rates[code.toLowerCase()]);
      if (value) map[code] = value;
    });
  }

  list.forEach((item) => {
    let code = String(item.code || item.currency || "").toUpperCase();
    if (code.endsWith("TRY") && code.length === 6) code = code.slice(0, 3);
    const value = parsePositiveRate(item.value ?? item.rate ?? item.try ?? item.TRY);
    if (["USD", "EUR", "RUB", "GEL"].includes(code) && value) map[code] = value;
  });

  const next = { TRY: 1, USD: map.USD || 0, EUR: map.EUR || 0, RUB: map.RUB || 0, GEL: map.GEL || 0 };
  if (!validExchangeRateMap(next)) {
    throw new Error("Kur verisi mantiksiz veya eksik geldi; eski sabit kur kullanilmadi.");
  }
  return next;
};
const tryRate = (currency) => {
  const code = normalizeCurrency(currency, "USD");
  if (code === "TRY") return 1;
  return parsePositiveRate(state.exchangeRates[code]);
};

const exchangeRate = (currency) => tryRate(currency) || 1;

const convertToUsd = (amount, currency) => {
  const value = Number(String(amount || 0).replace(",", "."));
  const code = normalizeCurrency(currency);
  if (code === "USD") return value;
  const usdTry = tryRate("USD");
  if (!usdTry) return 0;
  const valueTry = code === "TRY" ? value : value * (tryRate(code) || 0);
  return valueTry / usdTry;
};

const convertFromUsd = (usd, currency) => {
  const code = normalizeCurrency(currency);
  const value = Number(usd || 0);
  if (code === "USD") return value;
  const usdTry = tryRate("USD");
  if (!usdTry) return 0;
  const valueTry = value * usdTry;
  if (code === "TRY") return valueTry;
  const targetTry = tryRate(code);
  return targetTry ? valueTry / targetTry : 0;
};

const convertCurrency = (amount, fromCurrency, toCurrency, rates = state.exchangeRates) => {
  const numericAmount = Number(String(amount ?? 0).replace(/\s/g, "").replace(",", "."));
  if (!Number.isFinite(numericAmount)) return 0;
  let fromCode;
  let toCode;
  try {
    fromCode = normalizeCurrency(fromCurrency || "USD", "USD");
    toCode = normalizeCurrency(toCurrency || fromCode || "USD", fromCode || "USD");
  } catch (error) {
    console.warn("Kur dÃ¶nÃ¼ÅŸÃ¼mÃ¼ ÅŸu anda hesaplanamÄ±yor.", { fromCurrency, toCurrency, message: error.message });
    return numericAmount;
  }
  if (!fromCode || !toCode || fromCode === toCode) return numericAmount;
  const sourceRates = rates && typeof rates === "object" ? rates : state.exchangeRates;
  const rateFor = (code) => {
    if (code === "TRY") return 1;
    const direct = parsePositiveRate(sourceRates?.[code] ?? sourceRates?.[String(code).toLowerCase()]);
    return direct || tryRate(code);
  };
  const fromRate = rateFor(fromCode);
  const toRate = rateFor(toCode);
  if (!fromRate || !toRate) {
    console.warn("Kur dÃ¶nÃ¼ÅŸÃ¼mÃ¼ ÅŸu anda hesaplanamÄ±yor.", { fromCurrency: fromCode, toCurrency: toCode });
    return numericAmount;
  }
  const amountTry = fromCode === "TRY" ? numericAmount : numericAmount * fromRate;
  return toCode === "TRY" ? amountTry : amountTry / toRate;
};

