const invoiceLineCalc = (line) => {
  const qty = Number(line.quantity || 0);
  const calculate = (price) => {
    const d1 = Number(line.discount_1 || 0);
    const d2 = Number(line.discount_2 || 0);
    const d3 = Number(line.discount_3 || 0);
    const taxRate = Number(line.tax_rate || 0);
    const subtotal = qty * Number(price || 0);
    const net = [d1, d2, d3].reduce((amount, rate) => amount * (1 - rate / 100), subtotal);
    const discount = subtotal - net;
    const tax = net * taxRate / 100;
    return { subtotal, discount, net, tax, total: net + tax };
  };
  const current = calculate(line.current_unit_price ?? line.unit_price);
  const requested = calculate(line.requested_unit_price ?? line.unit_price);
  const priceDifference = requested.subtotal - current.subtotal;
  const discountPercentage = current.subtotal > 0 ? ((current.subtotal - requested.subtotal) / current.subtotal) * 100 : 0;
  return { ...requested, current, requested, priceDifference, discountPercentage };
};

const renderInvoiceProductPicker = () => {
  const tbody = document.querySelector("#invoiceProductRows");
  if (!tbody) return;
  const term = safeText(document.querySelector("#invoiceProductSearch")?.value).toLocaleLowerCase("tr");
  const invoiceType = document.querySelector("#invoiceForm")?.elements?.invoice_type?.value || "sale";
  const sorted = state.products
    .filter((item) => [item.name, item.brand, item.barcode, item.sku]
      .some((value) => safeText(value).toLocaleLowerCase("tr").includes(term)))
    .sort((a, b) => {
      const field = state.invoiceProductSort.field;
      const direction = state.invoiceProductSort.direction;
      const read = (item) => field === "stock"
        ? Number(item.stock_quantity || 0)
        : field === "price"
          ? productUnitPrice(item, invoiceType)
          : safeText(item[field]);
      const av = read(a);
      const bv = read(b);
      if (typeof av === "number" || typeof bv === "number") return direction === "desc" ? Number(bv) - Number(av) : Number(av) - Number(bv);
      return direction === "desc" ? String(bv).localeCompare(String(av), "tr") : String(av).localeCompare(String(bv), "tr");
    });
  tbody.innerHTML = sorted.length ? sorted.map((item) => {
    const currency = normalizeCurrency(item.currency || "USD");
    return `<tr data-picker-row="${escapeHtml(item.id)}"><td>${escapeHtml(item.barcode || item.sku || "-")}</td><td><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.brand || "")}</small></td><td>${number(item.stock_quantity || 0)}</td><td><input data-picker-qty type="number" min="0.001" step="0.001" value="1" /></td><td><input data-picker-price type="number" step="0.0001" value="${productUnitPrice(item, invoiceType)}" readonly aria-label="Mevcut birim fiyat" /></td><td><select data-picker-currency disabled><option selected>${currency}</option></select></td><td><select data-picker-unit><option value="adet">Adet</option><option value="koli">Koli</option></select></td><td><button data-add-invoice-product="${escapeHtml(item.id)}">Ekle</button></td></tr>`;
  }).join("") : '<tr><td colspan="8" class="empty">Ürün bulunamadı.</td></tr>';
};
