const updateInvoiceTermDays = () => {
  const form = document.querySelector("#invoiceForm");
  const out = document.querySelector("#invoiceTermDays");
  if (!form || !out) return;
  const invoiceDate = form.elements?.invoice_date?.value;
  const dueDate = form.elements?.due_date?.value;
  if (!invoiceDate || !dueDate) { out.textContent = "0 gun"; return; }
  const diff = Math.round((new Date(dueDate) - new Date(invoiceDate)) / 86400000);
  out.textContent = `${diff} gun`;
};

